-- Fase 2: inteligência financeira e orçamento gerencial.
CREATE TABLE IF NOT EXISTS public.financeiro_orcamentos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),empresa_id uuid NOT NULL REFERENCES public.empresas(id),categoria text NOT NULL,competencia date NOT NULL,valor_orcado numeric(14,2) NOT NULL CHECK(valor_orcado>=0),created_by uuid REFERENCES public.usuarios(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(empresa_id,categoria,competencia));
ALTER TABLE public.financeiro_orcamentos ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.financeiro_orcamentos FROM PUBLIC,anon,authenticated;
CREATE INDEX IF NOT EXISTS idx_fin_orc_empresa_competencia ON public.financeiro_orcamentos(empresa_id,competencia);
CREATE OR REPLACE FUNCTION public.app_admin_financeiro_relatorio(p_token text,p_tipo text,p_inicio date DEFAULT NULL,p_fim date DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','extensions' AS $function$
DECLARE v record; v_inicio date:=COALESCE(p_inicio,date_trunc('month',current_date)::date); v_fim date:=COALESCE(p_fim,current_date); v_tipo text:=lower(trim(coalesce(p_tipo,'fluxo')));
BEGIN
  SELECT * INTO v FROM public.app_tenant_usuario(p_token) LIMIT 1;
  IF v.usuario_id IS NULL OR v.perfil NOT IN ('admin','administrador','gestor') THEN RETURN jsonb_build_object('sucesso',false,'erro','Acesso negado'); END IF;
  IF v_tipo='fluxo' THEN RETURN jsonb_build_object('sucesso',true,'tipo',v_tipo,'inicio',v_inicio,'fim',v_fim,'linhas',(SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.mes),'[]'::jsonb) FROM (SELECT date_trunc('month',COALESCE(l.competencia,l.vencimento))::date mes,COALESCE(sum(l.valor) FILTER(WHERE l.tipo='receber' AND l.status='pago'),0) receitas_recebidas,COALESCE(sum(l.valor) FILTER(WHERE l.tipo='pagar' AND l.status='pago'),0) despesas_pagas,COALESCE(sum(l.valor) FILTER(WHERE l.tipo='receber' AND l.status IN('pendente','vencido')),0) receitas_previstas,COALESCE(sum(l.valor) FILTER(WHERE l.tipo='pagar' AND l.status IN('pendente','vencido')),0) despesas_previstas FROM public.financeiro_lancamentos l WHERE l.empresa_id=v.empresa_id AND COALESCE(l.competencia,l.vencimento) BETWEEN v_inicio AND v_fim GROUP BY 1 ORDER BY 1 LIMIT 24)x)); END IF;
  IF v_tipo='categorias' THEN RETURN jsonb_build_object('sucesso',true,'tipo',v_tipo,'inicio',v_inicio,'fim',v_fim,'linhas',(SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.valor DESC),'[]'::jsonb) FROM (SELECT COALESCE(NULLIF(trim(categoria),''),'Sem categoria') categoria,sum(valor) valor,count(*)::integer quantidade FROM public.financeiro_lancamentos WHERE empresa_id=v.empresa_id AND tipo='pagar' AND status<>'cancelado' AND vencimento BETWEEN v_inicio AND v_fim GROUP BY 1 ORDER BY 2 DESC LIMIT 50)x)); END IF;
  IF v_tipo IN ('contas_pagar','contas_receber') THEN RETURN jsonb_build_object('sucesso',true,'tipo',v_tipo,'inicio',v_inicio,'fim',v_fim,'linhas',(SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.vencimento),'[]'::jsonb) FROM (SELECT id,tipo,categoria,descricao,fornecedor,valor,competencia,vencimento,status,pago_em,origem,serie_id,parcela_numero,total_parcelas,observacoes FROM public.financeiro_lancamentos WHERE empresa_id=v.empresa_id AND tipo=CASE WHEN v_tipo='contas_pagar' THEN 'pagar' ELSE 'receber' END AND vencimento BETWEEN v_inicio AND v_fim ORDER BY vencimento LIMIT 500)x)); END IF;
  IF v_tipo='producao' THEN RETURN jsonb_build_object('sucesso',true,'tipo',v_tipo,'inicio',v_inicio,'fim',v_fim,'linhas',(SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.prazo),'[]'::jsonb) FROM (SELECT o.numero,o.descricao,c.nome cliente_nome,o.valor_total,o.status,o.status_pagamento,o.prazo FROM public.ordens_servico o LEFT JOIN public.clientes c ON c.id=o.cliente_id WHERE o.empresa_id=v.empresa_id AND o.status='entregue' AND o.prazo BETWEEN v_inicio AND v_fim ORDER BY o.prazo LIMIT 500)x)); END IF;
  IF v_tipo='dre' THEN RETURN jsonb_build_object('sucesso',true,'tipo',v_tipo,'inicio',v_inicio,'fim',v_fim,'linhas',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT 'Receitas realizadas' grupo,COALESCE(sum(valor),0) valor,100.0 participacao FROM public.financeiro_lancamentos WHERE empresa_id=v.empresa_id AND tipo='receber' AND status='pago' AND COALESCE(pago_em,vencimento) BETWEEN v_inicio AND v_fim UNION ALL SELECT 'Receitas previstas',COALESCE(sum(valor),0),0.0 FROM public.financeiro_lancamentos WHERE empresa_id=v.empresa_id AND tipo='receber' AND status IN('pendente','vencido') AND vencimento BETWEEN v_inicio AND v_fim UNION ALL SELECT 'Despesas pagas',COALESCE(sum(valor),0),0.0 FROM public.financeiro_lancamentos WHERE empresa_id=v.empresa_id AND tipo='pagar' AND status='pago' AND COALESCE(pago_em,vencimento) BETWEEN v_inicio AND v_fim UNION ALL SELECT 'Despesas previstas',COALESCE(sum(valor),0),0.0 FROM public.financeiro_lancamentos WHERE empresa_id=v.empresa_id AND tipo='pagar' AND status IN('pendente','vencido') AND vencimento BETWEEN v_inicio AND v_fim LIMIT 20)x)); END IF;
  IF v_tipo='inadimplencia' THEN RETURN jsonb_build_object('sucesso',true,'tipo',v_tipo,'inicio',v_inicio,'fim',v_fim,'linhas',(SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.ordem),'[]'::jsonb) FROM (SELECT '1 a 7 dias' faixa,1 ordem,count(*)::integer quantidade,COALESCE(sum(valor),0) valor FROM public.financeiro_lancamentos WHERE empresa_id=v.empresa_id AND tipo='receber' AND status IN('pendente','vencido') AND vencimento BETWEEN current_date-7 AND current_date-1 UNION ALL SELECT '8 a 30 dias',2,count(*)::integer,COALESCE(sum(valor),0) FROM public.financeiro_lancamentos WHERE empresa_id=v.empresa_id AND tipo='receber' AND status IN('pendente','vencido') AND vencimento BETWEEN current_date-30 AND current_date-8 UNION ALL SELECT '31 a 60 dias',3,count(*)::integer,COALESCE(sum(valor),0) FROM public.financeiro_lancamentos WHERE empresa_id=v.empresa_id AND tipo='receber' AND status IN('pendente','vencido') AND vencimento BETWEEN current_date-60 AND current_date-31 UNION ALL SELECT 'Mais de 60 dias',4,count(*)::integer,COALESCE(sum(valor),0) FROM public.financeiro_lancamentos WHERE empresa_id=v.empresa_id AND tipo='receber' AND status IN('pendente','vencido') AND vencimento < current_date-60 LIMIT 10)x)); END IF;
  IF v_tipo='recorrencias' THEN RETURN jsonb_build_object('sucesso',true,'tipo',v_tipo,'inicio',v_inicio,'fim',v_fim,'linhas',(SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.proximo_vencimento),'[]'::jsonb) FROM (SELECT descricao,categoria,fornecedor,periodicidade,valor,CASE periodicidade WHEN 'anual' THEN valor WHEN 'semanal' THEN valor*52 ELSE valor*12 END projecao_anual,proximo_vencimento FROM public.financeiro_recorrencias WHERE empresa_id=v.empresa_id AND ativo ORDER BY proximo_vencimento LIMIT 300)x)); END IF;
  IF v_tipo='orcamento' THEN RETURN jsonb_build_object('sucesso',true,'tipo',v_tipo,'inicio',v_inicio,'fim',v_fim,'linhas',(SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.orcado DESC),'[]'::jsonb) FROM (SELECT categoria,round(sum(orcado),2) orcado,round(sum(realizado),2) realizado,round(sum(orcado)-sum(realizado),2) desvio,CASE WHEN sum(orcado)>0 THEN round(sum(realizado)/sum(orcado)*100,1) ELSE 0 END execucao FROM (SELECT categoria,valor_orcado orcado,0::numeric realizado FROM public.financeiro_orcamentos WHERE empresa_id=v.empresa_id AND competencia BETWEEN v_inicio AND v_fim UNION ALL SELECT COALESCE(NULLIF(trim(categoria),''),'Sem categoria'),0::numeric,sum(valor) FROM public.financeiro_lancamentos WHERE empresa_id=v.empresa_id AND tipo='pagar' AND status='pago' AND COALESCE(competencia,vencimento) BETWEEN v_inicio AND v_fim GROUP BY categoria)s GROUP BY categoria ORDER BY 2 DESC LIMIT 100)x)); END IF;
  RETURN jsonb_build_object('sucesso',false,'erro','Tipo de relatório inválido');
END;$function$;
GRANT EXECUTE ON FUNCTION public.app_admin_financeiro_relatorio(text,text,date,date) TO anon,authenticated;
